mutation refundTransaction($transactionId: ID!, $amount: Amount, $orderId: String, $apiRequestKey: String) {
  refundTransaction(
    input: {
      transactionId: $transactionId
      apiRequestKey: $apiRequestKey
      refund: { amount: $amount, orderId: $orderId }
    }
  ) {
    refund {
      id
      legacyId
      status
      orderId
      createdAt
      amount {
        value
        currencyCode
      }
      processorAuthorizationResponse {
        legacyCode
        message
      }
      refundedTransaction {
        id
        status
      }
    }
  }
}

mutation reverseTransaction($transactionId: ID!, $apiRequestKey: String) {
  reverseTransaction(
    input: { transactionId: $transactionId, apiRequestKey: $apiRequestKey }
  ) {
    reversal {
      __typename
      ... on Transaction {
        id
        legacyId
        status
        amount {
          value
          currencyCode
        }
      }
      ... on Refund {
        id
        legacyId
        status
        amount {
          value
          currencyCode
        }
        processorAuthorizationResponse {
          legacyCode
          message
        }
      }
    }
  }
}

mutation sandboxSettleTransaction($transactionId: ID!) {
  sandboxSettleTransaction(input: { transactionId: $transactionId }) {
    transaction {
      id
      status
    }
  }
}

query searchCustomers($email: String, $first: Int = 50, $after: String) {
  customers(input: { email: { is: $email } }, first: $first, after: $after) {
    pageInfo {
      hasNextPage
      endCursor
    }
    edges {
      node {
        id
        legacyId
        email
        firstName
        lastName
        company
        phoneNumber
        createdAt
        defaultPaymentMethod {
          id
        }
      }
    }
  }
}

query searchDisputes($statuses: [DisputeStatus!], $first: Int = 50, $after: String) {
  disputes(input: { status: { in: $statuses } }, first: $first, after: $after) {
    pageInfo {
      hasNextPage
      endCursor
    }
    edges {
      node {
        id
        legacyId
        status
        type
        caseNumber
        referenceNumber
        receivedDate
        replyByDate
        createdAt
        amountDisputed {
          value
          currencyCode
        }
        transaction {
          id
          orderId
        }
      }
    }
  }
}

query searchTransactions($orderId: String, $createdFrom: Timestamp, $createdTo: Timestamp, $statuses: [PaymentStatus!], $first: Int = 50, $after: String) {
  transactions(
    input: {
      orderId: { is: $orderId }
      createdAt: { greaterThanOrEqualTo: $createdFrom, lessThanOrEqualTo: $createdTo }
      status: { in: $statuses }
    }
    first: $first
    after: $after
  ) {
    pageInfo {
      hasNextPage
      endCursor
    }
    edges {
      node {
        ...TransactionFields
      }
    }
  }
}

